bool StructTraits<::arc::mojom::CreateTimerRequest::DataView, ::arc::mojom::CreateTimerRequestPtr>::Read(
    ::arc::mojom::CreateTimerRequest::DataView input,
    ::arc::mojom::CreateTimerRequestPtr* output) {
  bool success = true;
  ::arc::mojom::CreateTimerRequestPtr result(::arc::mojom::CreateTimerRequest::New());
  
      if (success && !input.ReadClockId(&result->clock_id))
        success = false;
      if (success)
        result->expiration_fd = input.TakeExpirationFd();
  *output = std::move(result);
  return success;
}

